    private static int assertions;
    private static void check(boolean value,String why){assertions++;if(!value)throw new AssertionError(why);}
    private static byte[] bytes(DataInput in)throws IOException{byte[] out=new byte[in.readInt()];in.readFully(out);return out;}
    private static int[] ints(DataInput in)throws IOException{int[] out=new int[in.readInt()];for(int n=0;n<out.length;n++)out[n]=in.readInt();return out;}
    private static List<String> strings(DataInput in)throws IOException{List<String> out=new ArrayList<>();for(int n=in.readInt();n>0;n--)out.add(in.readUTF());return out;}
    private static final class Region{int address;byte[] bytes;}
    private static Region[] regions(DataInput in)throws IOException{Region[] out=new Region[in.readInt()];for(int n=0;n<out.length;n++){Region r=out[n]=new Region();r.address=in.readInt();r.bytes=bytes(in);}return out;}
    private static final class Image{int handle,width,height,stride,format;byte[] bytes;}
    private static final class Snapshot{byte[] frame;Region[] regions;int[] fields,clip,base,dirty;int active,rng,rngCalls;Image[] images;List<String> events;int journal;}
    private static Snapshot snapshot(DataInput in)throws IOException{Snapshot s=new Snapshot();s.frame=bytes(in);s.regions=regions(in);s.fields=ints(in);s.clip=ints(in);s.base=ints(in);s.dirty=ints(in);s.active=in.readInt();s.rng=in.readInt();s.rngCalls=in.readInt();s.images=new Image[in.readInt()];for(int n=0;n<s.images.length;n++){Image i=s.images[n]=new Image();i.handle=in.readInt();i.width=in.readInt();i.height=in.readInt();i.stride=in.readInt();i.format=in.readInt();i.bytes=bytes(in);}s.events=strings(in);s.journal=in.readInt();return s;}
    private static final class Owner implements Dc2Rain.State,Dc2Rain.Random,Dc2RainPipeline.Services {
        final TreeMap<Integer,byte[]> raw=new TreeMap<>();final Dc2Compositor compositor;final Dc2RainPipeline effects;final List<String> events=new ArrayList<>();final Map<Integer,int[][]> writes=new HashMap<>();final boolean pixels;final int loadHandle;final Map<String,int[][]> spriteWrites;int rng,rngCalls;
        Owner(Snapshot s,boolean pixels,int loadHandle,Map<Integer,int[][]> writes,Map<String,int[][]> spriteWrites)throws IOException{
            this.spriteWrites=spriteWrites;this.pixels=pixels;this.loadHandle=loadHandle;this.writes.putAll(writes);rng=s.rng;rngCalls=s.rngCalls;raw.put(0x9d8588,s.frame.clone());for(Region r:s.regions)raw.put(r.address,r.bytes.clone());for(int n=0;n<FIELDS.length;n++){raw.put(FIELDS[n],new byte[4]);writeInt(FIELDS[n],s.fields[n]);}
            Dc2Compositor c=null;for(Image i:s.images)if(i.format==0){NativeRgbImage image=NativeRgbImage.fromBgr24(i.width,i.height,i.stride,i.bytes);if(i.handle==0)c=new Dc2Compositor(image);else c.installRgb(i.handle,image);}else c.installAlpha(i.handle,NativeInverseAlphaImage.fromAbgr32(i.width,i.height,i.stride,i.bytes));compositor=c;if(s.active!=0)c.target(s.active);effects=new Dc2RainPipeline(this,c,this,this);
        }
        private byte[] region(int at)throws IOException{Map.Entry<Integer,byte[]> r=raw.floorEntry(at);if(r==null||at-r.getKey()>=r.getValue().length)throw new IOException("Unowned effect byte "+Integer.toHexString(at));return r.getValue();}
        private int readByte(int at)throws IOException{byte[] r=region(at);return r[at-raw.floorKey(at)]&255;}
        public int read(int at)throws IOException{return readInt(at);}
        public void write(int at,int value)throws IOException{writeInt(at,value);}
        public int readInt(int at)throws IOException{int v=0;for(int n=0;n<4;n++)v|=readByte(at+n)<<(n*8);return v;}
        public void writeByte(int at,int v)throws IOException{byte[] r=region(at);r[at-raw.floorKey(at)]=(byte)v;}
        public void writeInt(int at,int v)throws IOException{for(int n=0;n<4;n++)region(at+n);for(int n=0;n<4;n++)writeByte(at+n,v>>>(n*8));}
        public int next(){rng=rng*214013+2531011;rngCalls++;return rng>>>16&32767;}
        public int loadImage(int address,int mode){events.add("load,"+address+","+mode);return loadHandle;}
        public void freeImage(int handle){events.add("free,"+handle);}
        public void ensureTimer5(){events.add("timer5");}
        private void sprite(String name,Integer argument)throws IOException{events.add(name+(argument==null?"":","+argument));int[][] w=spriteWrites.get(name);if(w!=null)for(int[] a:w)writeInt(a[0],a[1]);}
        public void releaseSprites()throws IOException{sprite("releaseSprites",null);}
        public void updateSprites()throws IOException{sprite("updateSprites",null);}
        public void restoreSpriteRectangles()throws IOException{sprite("restoreSpriteRectangles",null);}
        public void drawSprites(int layer)throws IOException{sprite("drawSprites",layer);}
        private int pixel()throws IOException{Pc1Raster.Clip c=compositor.clip();return c.left>=c.right||c.top>=c.bottom?-1:compositor.rgb(compositor.activeTarget()).rgb(c.left,c.top);}
        public void redraw(int mask,int l,int t,int r,int b)throws IOException{Pc1Raster.Clip c=compositor.clip();events.add("redraw,"+mask+","+l+","+t+","+r+","+b+","+compositor.activeTarget()+","+c.left+","+c.top+","+c.right+","+c.bottom+","+pixel());compositor.setClip(l,t,r,b);c=compositor.clip();if(pixels&&c.left<c.right&&c.top<c.bottom)compositor.fill(c.left,c.top,c.left+1,c.top+1,(0x10101*mask+0x35172b)&0xffffff);int[][] w=writes.get(mask);if(w!=null)for(int[] f:w)writeInt(f[0],f[1]);}
        public void beginNativePaint()throws IOException{events.add("paintBegin");writeInt(0x96ba68,1);}
        public void paintRectangle(int l,int t,int r,int b){events.add("paint,"+l+","+t+","+r+","+b);}
        public void endNativePaint(){events.add("paintEnd");}
        void operation(String kind,int[] a)throws IOException{switch(kind){
            case"state":writeInt(a[0],a[1]);break;case"setClip":compositor.setClip(a[0],a[1],a[2],a[3]);break;case"target":compositor.target(a[0]);break;
            case"initializeRain":effects.initializeRain(a[0]);break;case"stop":effects.stop();break;case"update":effects.update();break;case"drawLayer":effects.drawLayer(a[0]);break;case"timerDrawLayer":effects.timerDrawLayer(a[0]);break;case"timerEffects":effects.timerEffects();break;
            case"record":effects.restore(a[0],a[1],a[2],a[3]);break;case"rotate":effects.rotateRectangles();break;case"redrawRectangles":effects.redrawRectangles(a[0]);break;case"overlap":effects.redrawOverlaps();break;case"paint":effects.paintRectangles();break;
            case"rainInit":Dc2Rain.initialize(this,this,effects,a[0]);break;case"rainUpdate":Dc2Rain.update(this,this);break;case"rainDraw":Dc2Rain.draw(this,effects,a[0]);break;case"rainRelease":Dc2Rain.release(this,effects);break;
            case"copy":compositor.copy(a[0],a[1],a[2]);break;case"transparent":compositor.transparent(a[0],a[1],a[2]);break;case"opacity":compositor.opacity(a[0],a[1],a[2],a[3]);break;case"feedback":compositor.feedback(a[0],a[1],a[2],a[3]);break;case"masked":compositor.masked(a[0],a[1],a[2],a[3]);break;case"scale":compositor.scale(a[0],a[1]);break;case"fill":compositor.fill(a[0],a[1],a[2],a[3],0x304020);break;case"fillBlend16":compositor.fillBlend16(a[0],a[1],a[2],a[3],0x304020,a[4]);break;case"present":compositor.present();break;
            default:throw new IOException("Unknown DC2 native fixture "+kind);
        }}
        void compare(Snapshot s,String name)throws IOException{
            check(Arrays.equals(raw.get(0x9d8588),s.frame),"Whole canonical frame "+name);for(Region r:s.regions){byte[] a=raw.get(r.address);check(Arrays.equals(a,r.bytes),"Whole effect raw/stale owner "+Integer.toHexString(r.address)+" "+name+diff(a,r.bytes));}for(int n=0;n<FIELDS.length;n++)check(readInt(FIELDS[n])==s.fields[n],"Borrowed effect field "+name);
            check(Arrays.equals(clip(compositor.clip()),s.clip),"Current clip "+name+Arrays.toString(clip(compositor.clip()))+" != "+Arrays.toString(s.clip));check(Arrays.equals(clip(compositor.baseClip()),s.base),"Base clip "+name);Pc1Raster.Rect d=compositor.rawDirty();check(Arrays.equals(new int[]{d.left,d.top,d.right,d.bottom},s.dirty),"Dirty union "+name);check(compositor.activeTarget()==s.active,"Target "+name);for(Image i:s.images){byte[] a=i.format==0?compositor.rgb(i.handle).bgr24():compositor.alpha(i.handle).abgr32();check(Arrays.equals(a,i.bytes),"Complete image/padding "+i.handle+" "+name+diff(a,i.bytes));}check(compositor.invalidations().size()==s.journal,"No invented present "+name);check(rng==s.rng&&rngCalls==s.rngCalls,"Shared CRT sequence "+name);check(events.equals(s.events),"Required service order/clip/pixel "+name+"\nactual="+events+"\nexpected="+s.events);
        }
    }
    private static String diff(byte[] a,byte[] b){if(a==null)return" missing";for(int n=0;n<a.length;n++)if(a[n]!=b[n])return" offset="+Integer.toHexString(n)+" actual="+(a[n]&255)+" expected="+(b[n]&255);return"";}
    private static int[] clip(Pc1Raster.Clip c){return new int[]{c.left,c.top,c.right,c.bottom};}
