    public static int run()throws Exception{
        assertions=0;check(VECTORS.length>0,"Native effects vectors present");Owner last=null;
        for(String vector:VECTORS){DataInputStream in=new DataInputStream(new InflaterInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(vector))));String name=in.readUTF();boolean pixels=in.readBoolean();int loadHandle=in.readInt();Map<Integer,int[][]> writes=new HashMap<>();for(int n=in.readInt();n>0;n--){int mask=in.readInt();int[][] w=new int[in.readInt()][];for(int k=0;k<w.length;k++)w[k]=ints(in);writes.put(mask,w);}Map<String,int[][]> spriteWrites=new HashMap<>();for(int n=in.readInt();n>0;n--){String key=in.readUTF();int[][] w=new int[in.readInt()][];for(int k=0;k<w.length;k++)w[k]=ints(in);spriteWrites.put(key,w);}Owner owner=new Owner(snapshot(in),pixels,loadHandle,writes,spriteWrites);last=owner;String error=null;for(int n=in.readInt();n>0;n--){String kind=in.readUTF();int[] a=ints(in);if(error==null)try{owner.operation(kind,a);}catch(IOException failure){error=failure.getMessage();}}Snapshot expected=snapshot(in);String nativeError=in.readUTF();check(nativeError.isEmpty()?error==null:error!=null,"Exact native known owner boundary "+name+" "+error);owner.compare(expected,name);}
        Dc2RainPipeline.Memory m=new Dc2RainPipeline.Memory(last);check(m.read(Dc2Rain.HANDLE)==-1&&m.read(Dc2Rain.LEVEL)==0,"DC2 PE handle/BSS defaults");m.write(Dc2Rain.RECORDS+1276,0x89abcdef);m.write(Dc2RainPipeline.BANK,1);m.write(Dc2RainPipeline.KIND,2);ByteArrayOutputStream out=new ByteArrayOutputStream();m.save(new DataOutputStream(out));check(out.size()==5304,"D2R1 exact owned bytes");Dc2RainPipeline.Memory.Image image=Dc2RainPipeline.Memory.load(new DataInputStream(new ByteArrayInputStream(out.toByteArray())));m.write(Dc2Rain.RECORDS+1276,0);m.write(Dc2RainPipeline.KIND,1);m.restore(image);check(m.read(Dc2Rain.RECORDS+1276)==0x89abcdef&&m.read(Dc2RainPipeline.KIND)==1,"Raw suffix restored,borrowed frame untouched");
        Dc2Compositor c=last.compositor;out=new ByteArrayOutputStream();c.save(new DataOutputStream(out));Dc2Compositor loaded=Dc2Compositor.load(new DataInputStream(new ByteArrayInputStream(out.toByteArray())));check(Arrays.equals(c.front().bgr24(),loaded.front().bgr24()),"D2O1 persistent front roundtrip");check(loaded.readNativeInt(Dc2Compositor.IMAGE_BASE+12)==loaded.width(0)&&loaded.readNativeInt(Dc2Compositor.ACTIVE)==loaded.activeTarget(),"DC2 native metadata addresses");loaded.setClip(2,3,30,40);check(loaded.readNativeInt(Dc2Compositor.CLIP_RIGHT+1)==(30>>>8|2<<24),"Unaligned adjoining DC2 clip alias");boolean rejected=false;try{loaded.readNativeInt(Dc2Compositor.IMAGE_BASE);}catch(IOException exact){rejected=true;}check(rejected,"No invented native heap pointer");rejected=false;try{loaded.writeNativeByte(Dc2Compositor.IMAGE_BASE+12,7);}catch(IOException exact){rejected=true;}check(rejected&&loaded.width(0)==96,"Unreviewed direct metadata writes are precise errors");final int[] calls={0};loaded.bindInvalidation(rect->{calls[0]++;check(loaded.clip().left==2,"OS invalidation before fullClip");});loaded.present();check(calls[0]==1&&loaded.clip().left==0,"Native invalidation sink ordering");
        Dc2RainPipeline missing=new Dc2RainPipeline(last,c,null,null);last.writeInt(Dc2RainPipeline.PENDING,1);missing.drawLayer(1);missing.update();check(true,"Suppressed branch needs no unused leaf");last.writeInt(Dc2RainPipeline.PENDING,0);rejected=false;try{missing.stop();}catch(IOException exact){rejected=exact.getMessage().contains("412340");}check(rejected&&last.readInt(Dc2RainPipeline.KIND)==0&&last.readInt(Dc2RainPipeline.COUNT)==0,"Missing active sprite release preserves completed native writes");return assertions;
    }
    public static void main(String[] args)throws Exception{System.out.println("DC2 rain pipeline assertions: "+run());}
